<?php
$ps=projectList();$total=count($ps);$budget=array_sum(array_column($ps,'budget_cents'));$released=array_sum(array_column($ps,'released_cents'));$spentTotal=array_sum(array_column($ps,'spent'));
$counts=['Ongoing'=>0,'Completed'=>0,'Pending'=>0,'Cancelled'=>0];foreach($ps as $p)$counts[$p['status']]++;
?>
<?php if($role==='admin'): ?>
<div class="grid three metrics"><?php metric('Total Users',(int)one('SELECT COUNT(*) n FROM users')['n'],'♙');metric('Total Projects',$total);metric('Total Fund',money((int)one('SELECT COALESCE(SUM(amount_cents),0) n FROM fund_entries')['n']),'₱'); ?></div>
<div class="grid two"><section class="panel"><div class="section-heading"><h2>Recent Activities</h2><a href="<?= e(url('audit')) ?>">View All</a></div><div class="table-wrap" tabindex="0" role="region" aria-label="Scrollable records"><table><thead><tr><th>Date</th><th>Action</th><th>User</th><th>Details</th></tr></thead><tbody><?php $logs=rows('SELECT l.*,u.name FROM audit_logs l LEFT JOIN users u ON u.id=l.user_id ORDER BY l.id DESC LIMIT 6');foreach($logs as $l): ?><tr><td><?= e(substr($l['created_at'],0,10)) ?></td><td><?= e($l['action']) ?></td><td><?= e($l['name']??'System') ?></td><td><?= e($l['details']) ?></td></tr><?php endforeach;if(!$logs)emptyRow(4); ?></tbody></table></div></section><?php chart($counts,'Project Overview'); ?></div>
<?php elseif($role==='official'): ?>
<h2>WELCOME SK OFFICIAL!</h2><div class="grid two"><section class="panel"><h2>Overview</h2><div class="grid two metrics"><?php metric('Total Projects',$total);metric('Ongoing Projects',$counts['Ongoing']); ?></div><?php chart($counts,'Project Status');$due=array_filter($ps,fn($p)=>$p['end_date']>=date('Y-m-d') && $p['end_date']<=date('Y-m-d',strtotime('+30 days')) && $p['status']!=='Completed'); ?><div class="grid two"><?php metric('Upcoming Due Dates',count($due),'▦');metric('Completed',$counts['Completed'],'✓'); ?></div></section><section class="panel"><h2>My Projects</h2><?php foreach(array_slice($ps,0,5) as $p)projectCard($p);if(!$ps)echo '<p class="empty">Your projects will appear here.</p>'; ?><a href="<?= e(url('projects')) ?>">Manage projects →</a></section></div>
<?php elseif($role==='chairperson' || $role==='treasurer'): ?>
<h2>WELCOME <?= $role==='chairperson'?'SK CHAIRPERSON':'SK TREASURER' ?>!</h2><div class="grid three metrics"><?php metric('Approved Budget',money($budget),'₱');metric('Total Fund Released',money($released),'₱');metric('Remaining Budget',money($budget-$spentTotal),'₱'); ?></div>
<div class="grid two"><?php chart($counts,'Project Status');$categories=[];foreach($ps as $p)$categories[$p['category']]=($categories[$p['category']]??0)+(int)$p['budget_cents']; ?><section class="panel"><h2>Fund Allocation</h2><?php barChart($categories); ?><div class="table-wrap" tabindex="0" role="region" aria-label="Scrollable records"><table><thead><tr><th>Category</th><th>Allocated Fund</th></tr></thead><tbody><?php foreach($categories as $name=>$amount): ?><tr><td><?= e($name) ?></td><td><?= money($amount) ?></td></tr><?php endforeach;if(!$categories)emptyRow(2); ?></tbody></table></div></section></div>
<?php if($role==='chairperson'):$pending=rows("SELECT r.*,p.title FROM fund_requests r JOIN projects p ON p.id=r.project_id WHERE r.status='Pending' ORDER BY r.id DESC"); ?>
<section class="panel"><div class="section-heading"><h2>Pending Items</h2><a href="<?= e(url('approvals')) ?>">Review requests →</a></div><div class="table-wrap" tabindex="0" role="region" aria-label="Scrollable records"><table><thead><tr><th>Project</th><th>Request</th><th>Amount</th></tr></thead><tbody><?php foreach($pending as $r): ?><tr><td><?= e($r['title']) ?></td><td><?= e($r['type']) ?></td><td><?= money($r['amount_cents']) ?></td></tr><?php endforeach;if(!$pending)emptyRow(3,'No pending fund requests.'); ?></tbody></table></div><p><a href="<?= e(url('proposals')) ?>"><?= count(array_filter($ps,fn($p)=>$p['review_status']==='Pending' || $p['publication_requested'])) ?> project proposals / publication requests to review</a></p></section>
<?php else: ?>
<section class="panel"><div class="section-heading"><h2>Recent Disbursements</h2><a href="<?= e(url('transactions')) ?>">View transactions →</a></div><div class="table-wrap" tabindex="0" role="region" aria-label="Scrollable records"><table><thead><tr><th>Date</th><th>Project</th><th>Amount</th></tr></thead><tbody><?php $recent=rows("SELECT r.*,p.title FROM fund_requests r JOIN projects p ON p.id=r.project_id WHERE r.type='Disbursement' AND r.status='Approved' ORDER BY r.decided_at DESC LIMIT 6");foreach($recent as $r): ?><tr><td><?= e($r['decided_at']) ?></td><td><?= e($r['title']) ?></td><td><?= money($r['amount_cents']) ?></td></tr><?php endforeach;if(!$recent)emptyRow(3); ?></tbody></table></div></section>
<?php endif ?>
<?php else: ?>
<h2>WELCOME, Youth / Residents!</h2><div class="grid three metrics"><?php metric('Total Projects',$total);metric('Ongoing Projects',$counts['Ongoing']);metric('Completed Projects',$counts['Completed']); ?></div><div class="grid two"><section class="panel"><div class="section-heading"><h2>Projects</h2><a href="<?= e(url('projects')) ?>">View All</a></div><?php foreach(array_slice($ps,0,5) as $p)projectCard($p,true);if(!$ps)echo '<p class="empty">No approved public projects yet.</p>'; ?></section><section class="panel"><h2>Latest Updates</h2><?php $updates=rows('SELECT l.*,p.title FROM progress_logs l JOIN projects p ON p.id=l.project_id WHERE p.published=1 ORDER BY l.id DESC LIMIT 8');foreach($updates as $log): ?><article><h3><?= e($log['title']) ?></h3><?= badge($log['status']) ?><p><?= e($log['details']) ?></p><small class="muted"><?= e($log['created_at']) ?></small></article><?php endforeach;if(!$updates)echo '<p class="empty">No published updates yet.</p>'; ?></section></div>
<?php endif ?>
